# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward‑model that recreates the *derived* outcomes found in the
    historical tables from the supplied `inputs` only.

    The algorithm groups the inputs by node and row index, pairs the
    numeric values that correspond to consecutive years, and emits
    one outcome for the change and one for the percent change.

    The produced outcome records have the same structure that the
    original `outcomes()` helper would generate: the key fields
    ``time``, ``kind``, ``entities``, ``value`` and the ``src`` list.
    """
    # ------------------------------------------------------------------
    # Load list lines for source metadata
    # ------------------------------------------------------------------
    all_list_lines: list[list] = []
    for node in doc.get("nodes", []):
        if node.get("kind") == "list":
            for li in range(len(node.get("lines", []))):
                all_list_lines.append([node["node_id"], li])

    # ------------------------------------------------------------------
    # Gather numeric values from the supplied inputs
    # ------------------------------------------------------------------
    # Mapping: (node_id, row_index) -> {year: amount}
    row_year_vals: dict[tuple[str, int], dict[int, float]] = {}
    row_entity_desc: dict[tuple[str, int], str] = {}

    for inp in inputs:
        # input id format: input:<node_id>:<row_index>:<col>
        parts = inp["id"].split(":")
        node_id = parts[1]
        # row index is taken from src (the first src entry)
        r_index = inp["src"][0][1]
        col_name = inp["src"][0][2][0]

        # Parse year from column name
        year_match = _year_regex.search(col_name)
        if not year_match:
            continue
        year = int(year_match.group(1))

        # Value is already parsed
        amount = inp["fields"]["amount"]
        if not isinstance(amount, (int, float)):
            try:
                amount = float(amount)
            except Exception:
                continue

        key = (node_id, r_index)
        row_year_vals.setdefault(key, {})[year] = amount

        # Entity description: part after 'entity:' in the first entity id
        if key not in row_entity_desc:
            ent_id_full = inp["entities"][0]
            ent_desc = ent_id_full.split(":", 1)[1]
            row_entity_desc[key] = ent_desc

    # ------------------------------------------------------------------
    # Build outcome records
    # ------------------------------------------------------------------
    outcomes_list: list[dict] = []

    for key, year_vals in row_year_vals.items():
        node_id, r_index = key
        years = sorted(year_vals.keys())
        if len(years) < 2:
            continue  # need at least two years for a change

        ent_desc = row_entity_desc[key]
        ent_id = f"entity:{_sanitize_id(ent_desc)}"

        # Compute change and percent between consecutive years
        for i in range(1, len(years)):
            y_curr = years[i]
            y_prev = years[i - 1]
            v_curr = year_vals[y_curr]
            v_prev = year_vals[y_prev]
            if not isinstance(v_curr, (int, float)) or not isinstance(v_prev, (int, float)):
                continue

            change = v_curr - v_prev
            percent = None
            if v_prev != 0:
                percent = (change / v_prev) * 100

            for val, label in [(change, "change"), (percent, "percent")]:
                if val is None:
                    continue
                out_id = f"outcome:{node_id}:{r_index}:{label}"
                rec = {
                    "time": None,
                    "kind": "derived",
                    "entities": [ent_id],
                    "value": val,
                    "src": [[node_id, r_index, [label]]],
                }
                rec["src"].extend(all_list_lines)
                outcomes_list.append(rec)

    return outcomes_list
